function showDeath() {
  if (!game) return;
  openOverlay(`
    <div class="overlay-card" style="max-width:560px">
      <p class="eyebrow" style="color:var(--danger)">The chamber closes</p>
      <h2>${escape(game.state.deathReason || 'The temple claims another.')}</h2>
