import { LEVELS, LEVEL_ORDER } from '/home/runner/work/PlayGround/PlayGround/js/data/levels.js';
import { DOCS, RELICS } from '/home/runner/work/PlayGround/PlayGround/js/data/story.js';

const DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
let fail = 0;
for (const id of LEVEL_ORDER) {
  const L = LEVELS[id];
  const w = L.map[0].length, h = L.map.length;
  const issues = [];
  L.map.forEach((r, i) => { if (r.length !== w) issues.push(`row ${i} width ${r.length}`); });
  const tile = (x, y) => L.map[y]?.[x] ?? '#';
  if (!['.', 'x', '~'].includes(tile(...L.start))) issues.push(`start on ${tile(...L.start)}`);
  if (!['.', 'x'].includes(tile(...L.exit))) issues.push(`exit on ${tile(...L.exit)}`);
  if (!['x'].includes(tile(...L.exit))) issues.push(`exit tile not x: ${tile(...L.exit)}`);
  const ents = L.entities || [];
  const blocking = new Set();
  for (const e of ents) {
    if (['#', 'o'].includes(tile(e.x, e.y)) && !['emitter'].includes(e.type)) issues.push(`${e.type}:${e.id} on ${tile(e.x, e.y)} @${e.x},${e.y}`);
    if (['block', 'mirror', 'dial', 'valve', 'guardian', 'emitter', 'target', 'door', 'hazard', 'platform'].includes(e.type)) {
      const k = `${e.x},${e.y}`;
      if (blocking.has(k)) issues.push(`overlap at ${k}`);
      blocking.add(k);
    }
    if (e.type === 'doc' && !DOCS[e.id]) issues.push(`unknown doc ${e.id}`);
    if (e.type === 'relic' && !RELICS[e.id]) issues.push(`unknown relic ${e.id}`);
    for (const p of e.path || []) if (!['.', 'x'].includes(tile(p[0], p[1]))) issues.push(`${e.type} path on ${tile(p[0], p[1])} @${p}`);
  }
  // reachability ignoring doors/hazards/platform waits, but treating mechanisms as blockers
  const waterHigh = !!L.waterHigh;
  const seen = new Set([L.start.join(',')]);
  const q = [L.start];
  while (q.length) {
    const [x, y] = q.shift();
    for (const [dx, dy] of DIRS) {
      const nx = x + dx, ny = y + dy, k = `${nx},${ny}`;
      if (seen.has(k)) continue;
      const t = tile(nx, ny);
      if (!['.', 'x', '~', 'o'].includes(t)) continue;
      if (t === '~' && !waterHigh) continue;
      if (t === 'o') continue;
      if (blocking.has(k)) {
        const e = ents.find((e) => e.x === nx && e.y === ny && ['block', 'mirror', 'dial', 'valve', 'guardian', 'emitter', 'target', 'door', 'hazard', 'platform'].includes(e.type));
        if (e && e.type !== 'door') continue;
      }
      seen.add(k); q.push([nx, ny]);
    }
  }
  const needs = ents.filter((e) => ['shard', 'relic', 'doc', 'key'].includes(e.type));
  const missing = needs.filter((e) => !seen.has(`${e.x},${e.y}`));
  // mechanism adjacency
  const unadj = [];
  for (const e of ents.filter((e) => ['dial', 'valve', 'mirror'].includes(e.type))) {
    const adj = DIRS.some(([dx, dy]) => seen.has(`${e.x + dx},${e.y + dy}`));
    if (!adj) unadj.push(`${e.type}:${e.id}`);
  }
  if (!seen.has(L.exit.join(','))) issues.push('EXIT unreachable (doors ignored?)');
  if (missing.length) issues.push('unreachable: ' + missing.map((e) => `${e.type}:${e.id}@${e.x},${e.y}`).join(' '));
  if (unadj.length) issues.push('no adjacent access: ' + unadj.join(' '));
  const shards = ents.filter((e) => e.type === 'shard').length;
  const docs = ents.filter((e) => e.type === 'doc').length;
  const relics = ents.filter((e) => e.type === 'relic').length;
  console.log(`${id}: ${w}x${h} shards=${shards} docs=${docs} relics=${relics} reach=${seen.size}${issues.length ? ' ISSUES: ' + issues.join(' | ') : ' OK'}`);
  if (issues.length) fail++;
}
console.log(fail ? `FAIL ${fail}` : 'ALL MAP CHECKS PASS');

import { Game } from '/home/runner/work/PlayGround/PlayGround/js/engine.js';
import { LEVELS, LEVEL_ORDER } from '/home/runner/work/PlayGround/PlayGround/js/data/levels.js';

const ACTIONS = [
  ['d', [1, 0]], ['a', [-1, 0]], ['s', [0, 1]], ['w', [0, -1]],
  ['E', 'interact'], ['W', 'wait'],
];

const clone = (o) => JSON.parse(JSON.stringify(o));

function hashState(s) {
  return JSON.stringify({
    g: s.grid, p: s.player, t: s.turn, wh: s.waterHigh, gs: s.glyphSeq, k: s.keys,
    cd: s.collectedDocs, cs: s.collectedShards, rc: s.relicCollected, st: s.status,
    e: s.entities.map((e) => [e.type, e.id, e.x, e.y, e.pathIndex, e.dir, e.value, e.open, e.pressed, e.triggered]),
  });
}

export function solve(levelId, maxStates = 400000) {
  const g = new Game(levelId);
  const start = clone(g.state);
