 await c.close();
 const levelStats={}; for(const id of ['1-1','1-2','1-3','2-1','2-2','3-1','3-2','4-1','4-2','5-1','5-2']) levelStats[id]={completed:true,stars:3};
 ({c,p}=await context({width:1280,height:800},{started:true,chapterIntroSeen:[1,2,3,4,5],levelStats,relics:['r1','r2','r3','r4','r5'],outfits:['default','wraith','singer','tide','archivist','sunforged']}));
 await p.locator('#btn-continue').click();
