 await p.locator('#btn-wardrobe').click();
 await p.locator('[data-outfit="sunforged"]').click();
 report.push(`wardrobe selection persisted=${(await p.evaluate(()=>JSON.parse(localStorage.getItem('solt_save_v1')).outfit))==='sunforged'}`);
 await p.locator('#btn-wardrobe-close').click();
 await p.locator('#btn-secret').click();
 const storyButtons=p.locator('#overlay-root button');
 if(await storyButtons.count()) await storyButtons.last().click();
 if(await p.locator('#btn-enter-level').count()) await p.locator('#btn-enter-level').click();
