 await p.locator('#btn-continue').click();await p.locator('#btn-secret').click();if(await p.locator('#btn-story-skip').count())await p.locator('#btn-story-skip').click();await p.waitForTimeout(100);await p.locator('#btn-enter-level').click();
 await route(p,'w w w w w w d d d d d d E E E s s s s s s E E a a a a a a a w w s s d d d w w a w w d s');
 await p.waitForTimeout(900);out.push(`secret completed result=${await p.locator('#btn-continue-level').count()===1}, save=${(await p.evaluate(()=>JSON.parse(localStorage.getItem('solt_save_v1')).secretDone))}`);
 await p.locator('#btn-continue-level').click();out.push(`secret outro=${await p.locator('#btn-story-skip').count()===1}`);await p.locator('#btn-story-skip').click();out.push(`secret outro returns map=${await p.locator('#screen-map').evaluate(e=>e.classList.contains('active'))}`);await c.close();
 ({c,p}=await open({started:true,chapterIntroSeen:[1,2,3,4,5],chapterOutroSeen:[1,2,3,4],levelStats:Object.fromEntries(['1-1','1-2','1-3','2-1','2-2','3-1','3-2','4-1','4-2','5-1'].map(id=>[id,{completed:true,stars:3}])),relics:['r1','r2','r3','r4','r5'],outfits:['default','wraith','singer','tide','archivist','sunforged']}));
 await p.locator('#btn-continue').click();await p.locator('[data-level="5-2"]').click();await p.locator('#btn-enter-level').click();
 await route(p,'d a s d d d E d d d d d a a a w w W w a d w w d d a a w w a a a a a d d d s E w d d d W d d');
 await p.waitForTimeout(900);out.push(`5-2 completed result=${await p.locator('#btn-continue-level').count()===1}`);await p.locator('#btn-continue-level').click();out.push(`ending story=${await p.locator('#btn-story-skip').count()===1}`);await p.locator('#btn-story-skip').click();out.push(`credits shown=${await p.locator('#btn-credits-map').count()===1}, total=${await p.locator('.stat-grid').innerText()}`);await p.locator('#btn-credits-map').click();out.push(`credits return map=${await p.locator('#screen-map').evaluate(e=>e.classList.contains('active'))}`);await c.close();
